    let snapshot = path.to_string_lossy().to_string();
    let diagnostics = test_path(
        Path::new("pyupgrade").join(path).as_path(),
        &settings::LinterSettings::for_rule(rule_code),
    )?;
    assert_messages!(snapshot, diagnostics);
    Ok(())
}

